func join(prefix, suffix string) string {
	if suffix == "" {
		return prefix
	}
	return strings.Join([]string{prefix, suffix}, "-")
}

func currenciesToMap(curs []models.Currency) map[string]string {
	m := make(map[string]string, len(curs))
	for _, c := range curs {
		m[c.ID] = c.Enum.String()
	}
	return m
}

